import json, sys
data = json.load(sys.stdin)
if isinstance(data, list):
    if len(data) == 0:
        print('No public repos found.')
    for r in data:
        print(f\"{r['name']}  |  {r.get('description','-')}  |  {'Private' if r['private'] else 'Public'}  |  Stars: {r['stargazers_count']}  |  Updated: {r['updated_at'][:10]}\")
